source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def runs(row):
        result, c = [], 0
        while c < w:
            d = c + 1
            while d < w and row[d] == row[c]:
                d += 1
            if row[c] != bg and d - c >= 2:
                result.append((row[c], c, d))
            c = d
        return result

    # Opposite horizontal bars: project each marker onto the lower bar,
    # then extend a short stem upward from the marker toward the upper bar.
    top = next(iter(runs(grid[0])), None)
    bottom = next((x for x in runs(grid[-1]) if top and x[0] == top[0]), None)
    if top and bottom:
        _, ts, te = top
        _, bs, be = bottom
        bars = {(0, c) for c in range(ts, te)} | {(h - 1, c) for c in range(bs, be)}
        markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
                   if grid[r][c] != bg and (r, c) not in bars]
        for r, c, color in markers:
            target = bs + (c - ts)
            if 0 <= target < w:
                for rr in range(h):
                    if (rr, target) not in bars and out[rr][target] == bg:
                        out[rr][target] = color
                # Upper projection is omitted when the gap is only one cell.
                if r - 1 >= 2:
                    for rr in range(1, r):
                        if out[rr][c] == bg:
                            out[rr][c] = color
                out[r][c] = 4
        return out

    # Opposite vertical bars (the rotated layout): connect the marker rows
    # back to the left edge and extend the lower right-hand bar horizontally.
    left = []
    for r in range(h):
        if grid[r][0] != bg:
            left.append(r)
    right = [r for r in range(h) if grid[r][w - 1] != bg]
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != bg
               and not (c == 0 and r in left) and not (c == w - 1 and r in right)]
    if left and right and markers:
        color = markers[0][2]
        for r, c, _ in markers:
            for cc in range(1, c):
                if out[r][cc] == bg:
                    out[r][cc] = color
            out[r][c] = 4
        for r in range(max(right) - 1, max(right) + 1):
            if 0 <= r < h:
                for c in range(w - 1):
                    if out[r][c] == bg:
                        out[r][c] = color
        return out
    return out
'''
